const nav = [['dashboard','概览'],['orders','维修工单'],['tasks','维保任务'],['devices','设备台账']];

function badge(status) {
  if (status === '待派单' || status === '异常待处理') return 'needs';
  if (status === '维修中' || status === '检修中') return 'progress';
  if (status === '待验收') return 'review';
  return 'done';
}

function workItems(orders,h) {
  return orders.map((order,index)=>`<article class="quiet-work-item" data-searchable="${h(`${order.id} ${order.device} ${order.title}`)}">
    <span class="quiet-index">${String(index+1).padStart(2,'0')}</span>
    <div class="quiet-work-copy"><small>${h(order.device)} <i>·</i> ${h(order.id)}</small><strong>${h(order.title)}</strong><span>${h(order.location)} · ${h(order.time)}</span></div>
    <span class="quiet-state ${badge(order.status)}">${h(order.status)}</span>
    <button type="button" data-action="open-order" data-id="${h(order.id)}" aria-label="查看 ${h(order.id)}">打开 <span aria-hidden="true">↗</span></button>
  </article>`).join('');
}

function taskItems(tasks,h) {
  return tasks.map(task=>`<article class="quiet-task" data-searchable="${h(`${task.title} ${task.device}`)}"><div class="quiet-task-icon">${task.status==='待执行'?'◌':'✓'}</div><div><strong>${h(task.title)}</strong><span>${h(task.device)} · ${h(task.owner)} · ${h(task.steps)}</span></div><small class="${task.due.includes('超期')?'is-late':''}">${h(task.due)}</small>${task.status==='待执行'?`<button type="button" data-action="complete-task" data-id="${h(task.id)}">完成任务</button>`:'<span class="quiet-finished">已完成</span>'}</article>`).join('');
}

function deviceItems(devices,h) {
  return devices.map(device=>`<article class="quiet-device" data-searchable="${h(`${device.name} ${device.code} ${device.place}`)}"><div><small>${h(device.code)} / ${h(device.kind)}</small><h3>${h(device.name)}</h3><p>${h(device.place)}</p></div><span class="quiet-state ${badge(device.health)}">${h(device.health)}</span><button type="button" data-action="open-device" data-id="${h(device.id)}">查看设备 ↗</button></article>`).join('');
}

function dashboard(m,h) {
  const active=m.orders.filter(order=>order.status!=='已关闭');
  return `<section class="quiet-hero"><div class="quiet-hero-text"><span class="quiet-overline">TUESDAY / 09.29　·　试点工厂</span><h1>把今天的工作，<br><em>安排得清清楚楚。</em></h1><p>维修、巡检和设备状态汇在一处。先解决影响生产的事，再完成计划内工作。</p><div class="quiet-hero-actions"><button type="button" data-action="new-report">发起报修 <span aria-hidden="true">↗</span></button><button type="button" data-action="nav" data-view="tasks">查看今日任务</button></div></div><div class="quiet-hero-number"><small>TODAY'S FOCUS</small><strong>${m.activeOrders.toString().padStart(2,'0')}</strong><span>件进行中的维修工单</span><div class="quiet-hero-line"></div><p>紧急事项 ${m.urgentOrders} 件　·　待执行维保 ${m.pendingTasks} 项</p></div></section>
    <section class="quiet-numbers" aria-label="今日统计"><div><small>01 / ASSETS</small><strong>${m.devices.length}</strong><span>已建档设备</span></div><div><small>02 / WORK ORDERS</small><strong>${m.activeOrders}</strong><span>待跟进工单</span></div><div><small>03 / MAINTENANCE</small><strong>${m.pendingTasks}</strong><span>待执行任务</span></div><div><small>04 / PRIORITY</small><strong>${m.urgentOrders}</strong><span>紧急事项</span></div></section>
    <div class="quiet-content-grid"><section class="quiet-work"><header><div><span>01 / TODAY'S WORK</span><h2>正在推进的维修</h2></div><button type="button" data-action="nav" data-view="orders">查看全部工单 ↗</button></header>${workItems(active,h)}</section><aside class="quiet-side"><section class="quiet-side-note"><span>本班提示</span><h2>先处理异常，<br>再回到计划。</h2><p>空压机压力异常已有报修记录。完成派单后，再跟进输送线验收与点检任务。</p><button type="button" data-action="open-order" data-id="WO-2048">查看紧急工单 ↗</button></section><section class="quiet-side-task"><header><span>02 / UPCOMING</span><h2>接下来的维保</h2></header>${taskItems(m.tasks.slice(0,2),h)}<button class="quiet-more" type="button" data-action="nav" data-view="tasks">全部维保任务 ↗</button></section></aside></div>`;
}

function orders(m,h){return `<section class="quiet-page-head"><span class="quiet-overline">WORK ORDERS / 维修工单</span><h1>每一张工单，<em>都有下文。</em></h1><p>在一条清楚的列表里核对故障、设备与下一步。</p><button type="button" data-action="new-report">发起新报修 ↗</button></section><section class="quiet-list-wrap"><div class="quiet-list-tools"><div>${[['all','全部'],['待派单','待派单'],['维修中','维修中'],['待验收','待验收']].map(([value,label])=>`<button type="button" data-action="filter" data-filter="${value}" class="${m.filter===value?'active':''}">${label}</button>`).join('')}</div><input data-search-input type="search" aria-label="搜索工单" placeholder="搜索编号、设备或故障"></div>${workItems(m.ordersInView,h)}</section>`;}
function tasks(m,h){return `<section class="quiet-page-head"><span class="quiet-overline">MAINTENANCE / 点检与保养</span><h1>把计划落到<em>每一项检查。</em></h1><p>查看到期时间、执行人和检查项，完成操作会更新当前原型状态。</p></section><section class="quiet-list-wrap quiet-tasks-page">${taskItems(m.tasks,h)}</section>`;}
function devices(m,h){return `<section class="quiet-page-head"><span class="quiet-overline">EQUIPMENT / 设备档案</span><h1>找到设备，<em>找到来龙去脉。</em></h1><p>以设备为入口衔接位置、状态和维修动作。</p><button type="button" data-action="new-report">发起报修 ↗</button></section><section class="quiet-device-wrap"><div class="quiet-list-tools"><span>已建档 ${m.devices.length} 台</span><input data-search-input type="search" aria-label="搜索设备" placeholder="搜索设备、编码、位置"></div><div class="quiet-device-grid">${deviceItems(m.devices,h)}</div></section>`;}

const css=`<style>
.quiet{--modal-bg:#fffdf9;--modal-ink:#2e3631;--modal-soft:#f2efe8;--modal-accent:#a95d3c;--modal-muted:#7d827c;--modal-line:#e8e3d9;min-height:100vh;background:#f8f7f3;color:#293832;font-family:Inter,"Microsoft YaHei",system-ui,sans-serif}.quiet button{font:inherit}.quiet a{color:inherit}.quiet-top{height:75px;border-bottom:1px solid #e8e6df;display:flex;align-items:center;gap:46px;padding:0 max(36px,calc((100vw - 1370px)/2));background:#fdfcf9}.quiet-brand{display:flex;align-items:center;gap:10px;white-space:nowrap}.quiet-brand-mark{width:31px;height:31px;background:#2c5d50;border-radius:50%;color:#fff;display:grid;place-items:center;font-size:16px;font-family:Georgia,serif}.quiet-brand strong{display:block;font-size:15px;letter-spacing:.08em;font-weight:700}.quiet-brand small{display:block;color:#89928b;font-size:8px;letter-spacing:.18em;margin-top:3px}.quiet-nav{display:flex;align-items:stretch;gap:32px;height:100%}.quiet-nav button{border:0;border-bottom:2px solid transparent;background:transparent;color:#87918a;font-size:12px;padding:0 2px}.quiet-nav button[aria-current=page]{border-color:#a85e3d;color:#354d42;font-weight:650}.quiet-nav button:hover{color:#a85e3d}.quiet-top-right{margin-left:auto;display:flex;gap:11px;align-items:center}.quiet-top-right span{color:#89928a;font-size:11px;white-space:nowrap}.quiet-top-right button{border:1px solid #e6e3da;border-radius:50%;width:33px;height:33px;color:#576c5e;background:white;font-size:14px;position:relative}.quiet-top-right button em{position:absolute;right:-5px;top:-6px;background:#b96544;color:white;border-radius:10px;padding:1px 4px;font-size:9px;font-style:normal}.quiet-main{max-width:1370px;padding:38px 36px 110px;margin:auto}.quiet-main>*{animation:quiet-enter 230ms ease-out both}.quiet-overline{font-size:10px;color:#a56546;letter-spacing:.16em;font-weight:700}.quiet-hero{display:grid;grid-template-columns:minmax(0,1.75fr) minmax(280px,.9fr);min-height:317px;background:#f3f0e8;border:1px solid #e8e2d5;border-radius:10px;overflow:hidden}.quiet-hero-text{padding:34px 46px 35px}.quiet-hero h1,.quiet-page-head h1{font-family:Georgia,"Songti SC","Noto Serif CJK SC",serif;font-size:38px;line-height:1.36;font-weight:600;letter-spacing:-.045em;margin:18px 0 14px}.quiet-hero h1 em,.quiet-page-head h1 em{font-style:normal;color:#ad6947}.quiet-hero p,.quiet-page-head p{color:#75827a;font-size:12px;line-height:1.85;max-width:540px;margin:0}.quiet-hero-actions{display:flex;gap:11px;margin-top:26px}.quiet-hero-actions button,.quiet-page-head>button{border:1px solid #2d6453;background:#2d6453;color:#fff;padding:11px 18px;border-radius:5px;font-size:12px;font-weight:600;min-height:42px}.quiet-hero-actions button:nth-child(2){background:transparent;color:#456d5c;border-color:#b7c9bc}.quiet-hero-number{display:flex;flex-direction:column;justify-content:center;padding:35px 42px;border-left:1px solid #e3dccd;background:linear-gradient(150deg,#f1eee5,#ece8db)}.quiet-hero-number small{font-size:10px;letter-spacing:.17em;color:#a66f51;font-weight:700}.quiet-hero-number strong{font-family:Georgia,serif;font-size:108px;font-weight:400;line-height:1;margin:10px 0 3px;color:#36594d;letter-spacing:-.08em}.quiet-hero-number>span{font-size:13px;font-weight:600;color:#516759}.quiet-hero-line{height:1px;background:#d4cbb9;margin:21px 0 13px}.quiet-hero-number p{font-size:11px}.quiet-numbers{display:grid;grid-template-columns:repeat(4,1fr);border-bottom:1px solid #e8e4dc;margin:31px 0 37px;padding-bottom:25px}.quiet-numbers>div{display:grid;grid-template-columns:64px auto;grid-template-rows:auto auto;column-gap:10px;padding:5px 20px;border-right:1px solid #e8e4dc}.quiet-numbers>div:first-child{padding-left:0}.quiet-numbers>div:last-child{border-right:0}.quiet-numbers small{grid-column:1/-1;color:#a2a6a0;letter-spacing:.1em;font-size:9px;margin-bottom:10px}.quiet-numbers strong{grid-row:2;font-family:Georgia,serif;color:#375c4f;font-size:41px;line-height:1}.quiet-numbers span{grid-row:2;color:#738078;font-size:11px;align-self:end;padding-bottom:4px;white-space:nowrap}.quiet-content-grid{display:grid;grid-template-columns:minmax(0,1.5fr) minmax(320px,.8fr);gap:46px}.quiet-work>header,.quiet-side-task header{display:flex;justify-content:space-between;align-items:end;border-bottom:1px solid #dcded6;padding-bottom:17px}.quiet-work header span,.quiet-side-task header span{color:#aa765c;letter-spacing:.13em;font-size:9px;font-weight:700}.quiet-work h2,.quiet-side-task h2{font-family:Georgia,"Songti SC",serif;font-size:20px;margin:7px 0 0;letter-spacing:-.02em}.quiet-work header button,.quiet-side-note button,.quiet-more{border:0;background:transparent;color:#a66344;font-size:11px;padding:6px 0;font-weight:600}.quiet-work-item{display:flex;align-items:center;gap:17px;border-bottom:1px solid #e6e7e0;min-height:94px;padding:14px 0}.quiet-index{font-family:Georgia,serif;font-size:21px;color:#c5c5b9;width:25px;flex:none}.quiet-work-copy{flex:1;min-width:0}.quiet-work-copy small{font-size:10px;color:#a07d65}.quiet-work-copy strong{display:block;margin:6px 0;font-size:14px;font-weight:600;color:#30433a}.quiet-work-copy>span{display:block;color:#98a39b;font-size:10px}.quiet-work-copy i{font-style:normal;margin:0 4px}.quiet-state{border-radius:30px;padding:5px 9px;font-size:10px;white-space:nowrap}.quiet-state.needs{background:#f4e7dc;color:#b26744}.quiet-state.progress{background:#e5ecea;color:#527f72}.quiet-state.review{background:#eae7ef;color:#827293}.quiet-state.done{background:#edf0e8;color:#69826d}.quiet-work-item>button,.quiet-device>button{border:0;background:transparent;color:#a16a51;font-size:11px;white-space:nowrap}.quiet-work-item>button span{margin-left:4px}.quiet-side{display:grid;gap:27px;align-content:start}.quiet-side-note{padding:26px 29px;border:1px solid #e1e2d8;background:#f0f1e9;border-radius:8px}.quiet-side-note>span{color:#809678;font-size:10px;font-weight:700;letter-spacing:.12em}.quiet-side-note h2{font-family:Georgia,"Songti SC",serif;font-size:23px;line-height:1.4;margin:19px 0 10px;color:#425f4e}.quiet-side-note p{font-size:11px;line-height:1.8;color:#829087;margin:0 0 14px}.quiet-side-task header{border-bottom:1px solid #e6e6de}.quiet-task{display:flex;align-items:center;gap:10px;padding:16px 0;border-bottom:1px solid #e6e7e0}.quiet-task-icon{width:27px;height:27px;display:grid;place-items:center;border-radius:50%;background:#e5ede5;color:#63836c;flex:none;font-size:18px}.quiet-task>div:nth-child(2){flex:1;min-width:0}.quiet-task strong{display:block;font-size:12px;white-space:nowrap;overflow:hidden;text-overflow:ellipsis}.quiet-task span{display:block;color:#9ba89e;font-size:10px;margin-top:5px}.quiet-task small{font-size:10px;color:#7d9283;white-space:nowrap}.quiet-task small.is-late{color:#af6749}.quiet-task>button{border:0;background:#e8ede5;color:#4a7659;padding:8px 10px;border-radius:5px;font-size:10px}.quiet-finished{font-size:10px;color:#799a7c!important}.quiet-more{margin-top:13px}.quiet-page-head{position:relative;max-width:770px;margin:15px 0 30px}.quiet-page-head h1{font-size:34px;margin:10px 0}.quiet-page-head>button{margin-top:20px}.quiet-list-wrap,.quiet-device-wrap{background:#fdfcf9;border:1px solid #eae9e2;border-radius:8px;padding:16px 28px}.quiet-list-tools{display:flex;align-items:center;justify-content:space-between;gap:15px;padding:9px 0 17px;border-bottom:1px solid #e6e7e0;font-size:11px;color:#929e94}.quiet-list-tools>div{display:flex;gap:6px;flex-wrap:wrap}.quiet-list-tools button{border:0;background:transparent;color:#8e988e;padding:8px 12px;border-radius:20px;font-size:11px}.quiet-list-tools button.active{background:#e4ebe2;color:#345f48;font-weight:700}.quiet-list-tools input{border:1px solid #e3e6df;background:white;border-radius:4px;min-width:230px;padding:9px 11px;font-size:11px}.quiet-tasks-page{padding-top:5px}.quiet-tasks-page .quiet-task{min-height:92px}.quiet-device-grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:13px;margin-top:18px}.quiet-device{border:1px solid #e7e9e0;background:#fff;border-radius:6px;padding:24px;min-height:160px;display:flex;flex-direction:column;align-items:flex-start}.quiet-device>div{flex:1}.quiet-device small{color:#aa7b61;letter-spacing:.08em;font-size:10px}.quiet-device h3{font-size:18px;margin:13px 0 7px;font-weight:600}.quiet-device p{font-size:11px;color:#92a096;margin:0}.quiet-device .quiet-state{margin:12px 0}.quiet-device button{padding:4px 0}.quiet .proto-modal{border:1px solid #dfdacf;border-radius:7px}.quiet .proto-modal h2{font-family:Georgia,"Songti SC",serif}.quiet .proto-modal-actions button{border-radius:4px}@keyframes quiet-enter{from{opacity:0;transform:translateY(8px)}to{opacity:1;transform:translateY(0)}}
@media(max-width:1050px){.quiet-top{padding:0 24px;gap:25px}.quiet-nav{gap:16px}.quiet-main{padding:30px 25px 100px}.quiet-content-grid{grid-template-columns:1fr;gap:30px}.quiet-side{grid-template-columns:1fr 1fr}.quiet-hero{grid-template-columns:1.4fr 1fr}.quiet-hero-text{padding:32px}.quiet-hero-number{padding:27px}.quiet-numbers>div{padding:5px 11px}}
@media(max-width:700px){.quiet-top{padding:13px 16px;height:auto;display:block}.quiet-brand{margin-bottom:9px}.quiet-nav{height:40px;gap:15px;overflow:auto}.quiet-nav button{white-space:nowrap}.quiet-top-right{position:absolute;right:16px;top:16px}.quiet-top-right>span{display:none}.quiet-main{padding:23px 16px 90px}.quiet-hero{display:block}.quiet-hero-text{padding:25px}.quiet-hero h1{font-size:27px}.quiet-hero-number{display:none}.quiet-numbers{grid-template-columns:repeat(2,1fr);row-gap:17px;margin:24px 0}.quiet-numbers>div:nth-child(2){border-right:0}.quiet-numbers strong{font-size:34px}.quiet-side{grid-template-columns:1fr}.quiet-content-grid{gap:24px}.quiet-work-item{gap:9px;flex-wrap:wrap}.quiet-work-copy{flex-basis:58%}.quiet-work-item .quiet-state{margin-left:34px}.quiet-list-wrap,.quiet-device-wrap{padding:12px 17px}.quiet-list-tools{flex-wrap:wrap}.quiet-list-tools input{width:100%}.quiet-device-grid{grid-template-columns:1fr}.quiet-page-head h1{font-size:27px}}
@media(prefers-reduced-motion:reduce){.quiet-main>*{animation:none}}
</style>`;

export default {
  className:'quiet',
  render(m,h){return `${css}<div class="quiet-shell"><header class="quiet-top"><div class="quiet-brand"><span class="quiet-brand-mark">维</span><div><strong>设备维保</strong><small>THE WORKBENCH</small></div></div><nav class="quiet-nav" aria-label="工作区导航">${nav.map(([view,label])=>`<button type="button" data-action="nav" data-view="${view}" ${m.view===view?'aria-current="page"':''}>${label}</button>`).join('')}</nav><div class="quiet-top-right"><span>演示环境 · 09月29日</span><button type="button" data-action="notifications" aria-label="消息中心">◌${m.unread?`<em>${m.unread}</em>`:''}</button></div></header><div class="quiet-main">${m.view==='dashboard'?dashboard(m,h):m.view==='orders'?orders(m,h):m.view==='tasks'?tasks(m,h):devices(m,h)}</div></div>`;}
};
